    p=newProject(0);p.sections={{Section::main,4,"One"},{Section::drop,4,"Two"}};p.normalise();const auto before=p;AiOptions options;options.wholeSong=false;options.section=1;options.tracks={0};Project compiled;juce::String summary;
    const auto plan=R"({"sections":[{"bars":4},{"bars":4}],"patterns":[{"id":"p","track":0,"beats":4,"notes":[[0,72,1,100]]}],"clips":[{"section":0,"pattern":"p"},{"section":1,"pattern":"p"}],"summary":"Selected section"})";
    result=aiCompile(p,options,plan,compiled,summary);require(result.wasOk(),result.getErrorMessage().toRawUTF8());require(compiled.tracks[0].clips[0]==before.tracks[0].clips[0]&&compiled.tracks[1].clips==before.tracks[1].clips,"section AI changed excluded data");require(compiled.tracks[0].clips[1].notes!=before.tracks[0].clips[1].notes,"section AI did not update selected take");
    p.tracks[0].freeTimeline=true;Clip crossing;crossing.position=8;crossing.span=32;crossing.notes={{0,32,60,100,0}};p.tracks[0].clips={crossing};result=aiCompile(p,options,plan,compiled,summary);require(result.wasOk(),"section AI rejected independent timeline");require(compiled.clipAtBeat(0,9)>=0&&compiled.clipAtBeat(0,33)>=0,"section AI erased outside independent regions");
